import { maskCredential } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}

function masked(input: string, expected: string): void {
  const result = maskCredential(input);
  assert(result.ok === true, `expected successful result for ${JSON.stringify(input)}`);
  equal(result.masked, expected, `mask for ${JSON.stringify(input)}`);
}

masked("a", "*");
masked("abcd", "****");
masked("abcde", "*bcde");
masked("  secret1234  ", "******1234");
masked("😀abc", "*😀abc");

const empty = maskCredential(" \t\n ");
assert(empty.ok === false, "trimmed empty credential fails");
equal(empty.message, "credential is empty", "empty credential message");

try {
  maskCredential(123 as unknown as string);
  throw new Error("non-string credential did not throw");
} catch (error) {
  assert(error instanceof TypeError, "non-string credential throws TypeError");
}

const first = maskCredential("abcdef");
const second = maskCredential("abcdef");
assert(first !== second, "returns fresh result objects");

